Object.assign(translations.de,{skip:'Zur interaktiven Demo',product:'Produkt',how:'So funktioniert’s',valueNav:'Raumwert',placeNav:'Möbel testen',discover:'Demo entdecken',home:'DEIN ZUHAUSE. WEITERGEDACHT.',heroTitle:'Dein Raum.<br><span>Neue Möglichkeiten.</span>',heroBody:'Entdecke dein Zuhause in 3D. Verstehe den Wert deiner Möbel. Und finde heraus, was als Nächstes zu dir passt.',explore3d:'Raum in 3D erkunden',browser:'Direkt im Browser entdecken · Ohne App-Installation',explore360:'360° erkunden',discoverValues:'Werte entdecken',furnish:'Neu einrichten',productDemo:'INTERAKTIVE PRODUKTDEMO',overviewEyebrow:'RAUMIO IN EINEM BLICK',overviewTitle:'Aus deinem Raum<br><span>wird eine Entscheidung.</span>',overviewBody:'RAUMIO verbindet Raumscan, Objekterkennung und Marktvergleich in einem verständlichen Ablauf. Du siehst, was in deinem Zuhause steckt, welchen Wert es ungefähr hat und wie neue Möbel darin wirken könnten.',overview1Title:'Erfassen',overview1Body:'Mit iPhone oder iPad den Raum aus mehreren Blickwinkeln aufnehmen und als begehbares 3D-Modell aufbauen.',overview2Title:'Verstehen',overview2Body:'Gegenstände zuordnen, Sicherheit sichtbar machen und ähnliche Gebrauchtangebote mit ihrer Herleitung zeigen.',overview3Title:'Weiterdenken',overview3Body:'Neue Möbel im gleichen Raum ausprobieren, Positionen vergleichen und später direkt passende Produkte finden.',overviewReady:'Heute als Konzeptdemo erlebbar',overviewOpen:'Jetzt den Raum öffnen',interactiveRoom:'Dein Raum, interaktiv.',explore:'Erkunden',values:'Werte',tryFurniture:'Möbel testen',fixed:'360° · FESTER STANDPUNKT',pricesOn:'Preise an',pricesOff:'Preise aus',hint:'Nach oben ziehen = Blick nach oben · Standpunkt bleibt fixiert',modeExplore:'Fester Standpunkt · Preise folgen dem tatsächlich anvisierten Modellteil',modePlace:'ROOM-ONLY · DRAUFSICHT · FLUR AUSGEBLENDET',inFocus:'IM FOKUS',inRoom:'IM RAUM',oneObject:'1 OBJEKT',categorySafe:'Kategorie bestätigt',probable:'Wahrscheinlich',identityOpen:'Identität offen',valuationOpen:'Bewertung offen',perPiece:'Angebotsspanne pro Stück · ähnliche Produkte',noValue:'Kein belastbarer Vergleichswert',sources:'recherchierte Vergleiche · Ähnlichkeit begrenzt',openSources:'Angebote & Preisgrundlage ↗',openSourcesTitle:'Preisgrundlage',allGroups:'Alle 6 Gruppen',filterObjects:'Objekte filtern',objectCol:'OBJEKT / ERKENNUNG',valueCol:'VERGLEICHSWERT',recommendCol:'EMPFEHLUNG',market:'Kleinanzeigen',comparisonOpen:'Vergleich offen',comparisonBasis:'Vergleichsangebote & Herleitung ansehen ↗',groups:'Objektgruppen',pieces:'Stück bewertet',assessed:'Bewerteter Teil des Raums',safeLabel:'Kategorie bestätigt',probableLabel:'Wahrscheinliche Zuordnung',valuationOpen:'Bewertung offen',openGroups:'Gruppen offen',research:'Angebotspreise ähnlicher Produkte · Recherche 22.09.2026',roomValueNote:'Teilwert der belegten Vergleichskategorien. Zwei Betten zählen doppelt. Unbewertete Möbel und weitere Gegenstände sind nicht enthalten. Der vollständige Raumwert bleibt offen.',statsView:'Fester Standpunkt. Freier Blick.',statsAssigned:'Manuell im Modell zugeordnet',statsValue:'Bewerteter Teil des Raums',statsNote:'Ein neuer Blick auf Dinge,<br>die schon da sind.',howEyebrow:'01 — SO FUNKTIONIERT’S',howTitle:'Ein neuer Blick.<br>In drei Schritten.',howBody:'Die Idee: Mit iPhone oder iPad durch den Raum gehen. Aus Wänden, Winkeln und Gegenständen wird ein Raum, mit dem du arbeiten kannst.',step1:'Raum erfassen',step1Body:'Die Kamera entlang der Wände bewegen und Ecken aus mehreren Blickwinkeln aufnehmen.',step2:'Dinge verstehen',step2Body:'Objekte zuordnen, Unsicherheiten sichtbar machen und unbekannte Gegenstände nachprüfen.',step3:'Möglichkeiten entdecken',step3Body:'Second-Hand-Werte vergleichen, eine Verkaufsplattform finden und neue Möbel ausprobieren.',cameraGeometry:'KAMERA → RAUMGEOMETRIE',objectsMatch:'OBJEKTE → ZUORDNUNG',roomOptions:'RAUM → MÖGLICHKEITEN',scanLabel:'SCAN-SIMULATION',scanTitle:'Von der Aufnahme zur Übersicht.',scanBody:'Erlebe den Ablauf mit Beispieldaten. Deine Kamera bleibt aus.',scanReady:'Bereit für den Demo-Scan',scanStart:'Demo-Scan starten ↗',scanSim:'simuliert',scanStage1:'Raumgeometrie erfassen …',scanStage1Body:'Die Simulation veranschaulicht das Zusammensetzen von Wänden und Ecken.',scanStage2:'Objektgruppen zuordnen …',scanStage2Body:'Die Beispieldaten unterscheiden bestätigte Kategorien, Vermutungen und offene Identitäten.',scanStage3:'Vergleichsangebote einbeziehen …',scanStage3Body:'Das Beispiel verwendet die hinterlegten, recherchierten Angebote. Keine Live-Abfrage.',scanStage4:'Dein Demo-Raum ist bereit.',scanStage4Body:'Die Objektübersicht zeigt belegte Teilwerte und offene Bewertungen.',scanResult:'Ergebnis ansehen <span>↗</span>',scanDone:'Demo-Scan abgeschlossen. Die Übersicht ist bereit.',disclosure:'Produktkonzept: Die Website rekonstruiert keine echten Räume und misst keine Abmessungen. Die Scan-Simulation greift auf die hinterlegte Objektliste zurück. Ein echter Scan und laufende Preisaktualisierungen benötigen später eine eigene Anbindung.',valueEyebrow:'02 — WERTE ENTDECKEN',valueTitle:'Gute Dinge.<br>Bleibender Wert.',valueIntro:'Behalte den Überblick. Jede Schätzung zeigt ihre Spanne und wie sicher die Zuordnung ist.',valuation:'BEWERTETER TEIL DES RAUMS',safeBar:'Kategorie bestätigt',likelyBar:'Wahrscheinliche Zuordnung',objectsOverview:'Deine Objektübersicht',legendSafe:'Kategorie im Modell bestätigt',legendLikely:'Wahrscheinliche Zuordnung',legendOpen:'Identität offen',confidenceNote:'Keine gemessenen KI-Confidence-Werte. Herstelleridentität bleibt ungeprüft.',placeEyebrow:'03 — VIRTUELL EINRICHTEN',placeTitle:'Passt es zu dir?<br>Finde es heraus.',placeIntro:'Passt der Sessel in die Ecke? Teste Position, Drehung und Farbe in derselben Raumidee als Draufsicht. Der Flur bleibt ausgeblendet.',furnitureDemo:'INTERAKTIVE MÖBEL-DEMO',placeHeading:'Dein nächster<br>Lieblingsplatz.',placeBody:'Wähle einen Sessel oder Beistelltisch. Verschiebe ihn auf dem Boden, drehe ihn und vergleiche die Farben.',openPlacement:'Möbel im Viewer testen',watchPlacement:'▷ Platzierung automatisch ansehen',futureTitle:'Dein Möbelmodell kommt als Nächstes.',futureBody:'Die zusätzliche 3D-Datei kann anschließend in diese Platzierungsansicht integriert werden.',inspiration:'RAUM FÜR DEINE IDEEN',inspiration2:'INSPIRATION',inspirationCaption:'Einrichtungsinspiration · KI-generiert',functionsEyebrow:'04 — DIE FUNKTIONEN',functionsTitle:'Alles verbunden.<br>Bis ins Detail.',functionsIntro:'Vom digitalen Raum zum passenden Möbelstück: Entdecke, was heute schon möglich ist und wohin sich RAUMIO entwickelt.',productConcept:'PRODUKTKONZEPT',inDemo:'IN DIESER DEMO',later:'VORBEREITET FÜR SPÄTER',f1:'Raumgeometrie & Maße',f1Body:'Wände, Boden, Türen und Fenster bilden die Grundlage des digitalen Raums. Ein späterer Scan soll mehrere Kamerablickwinkel zusammenführen und unvollständige Bereiche markieren.',f2:'Blickbasierte Objektkarten',f2Body:'Du bleibst an einem festen Punkt im Hotelzimmer. Ziehe den Blick in jede Richtung oder nutze die Pfeiltasten. Trifft das Fadenkreuz ein zugeordnetes Möbel, erscheint seine Karte.',f3:'Nachvollziehbare Preisvergleiche',f3Body:'Öffne die Preisgrundlage eines Möbels. Du siehst konkrete Anzeigen, Angebotspreise, Ähnlichkeiten und Abweichungen. Die Spanne stammt aus den ausgewählten Vergleichspreisen.',f4:'Sicherheit sichtbar machen',f4Body:'„Kategorie bestätigt“ bedeutet: Der Modellteil ist etwa als Bett benannt. „Wahrscheinlich“ lässt die genaue Einordnung offen. Zusammengefasste oder unklare Objekte erhalten keinen erfundenen Wert.',f5:'Möbel virtuell platzieren',f5Body:'In derselben Raumidee zeigt die Platzierungsansicht den Hotelraum von oben; der Flur ist ausgeblendet. Sessel und Tisch lassen sich verschieben, drehen und umfärben.',f6:'Verkaufen & passende Produkte kaufen',f6Body:'Vergleichsangebote führen direkt zur jeweiligen Anzeige. Die Möbel-Demo öffnet eine Produktsuche. Eine spätere Version kann Händlerprodukte und gekennzeichnete Affiliate-Links einbinden.',more:'Mehr zur Funktion',faqEyebrow:'GUT ZU WISSEN',faqTitle:'Offene Fragen.<br>Klare Antworten.',faq1:'Kann ich damit jetzt meine eigene Wohnung scannen?',faq1Body:'Noch nicht. Die Demo zeigt den geplanten Ablauf und ein vorhandenes Hotelzimmermodell. Für echte Scans braucht das Produkt eine Aufnahme- und Rekonstruktionslösung, beispielsweise eine dafür entwickelte iPhone-/iPad-Anwendung. Die Website fordert keinen Kamerazugriff an.',faq2:'Wie entsteht der angezeigte Raumwert?',faq2Body:'Die bewertete Teilsumme addiert die unteren beziehungsweise oberen Preise der ausgewählten Vergleichsangebote pro Kategorie. Zwei Betten werden zweimal gezählt. Kategorien ohne brauchbare Preisgrundlage und weitere Gegenstände fehlen bewusst in der Summe. Ein vollständiger Raumwert wird deshalb noch nicht behauptet.',faq3:'Sind das exakt dieselben Möbel wie im Modell?',faq3Body:'Nein. Die Modellinformationen belegen keine Hersteller oder Artikelnummern. Wir zeigen form- und funktionsähnliche Produkte, deren Unterschiede bei jedem Vergleich genannt werden. Die Preisgrundlage ist ein recherchierter Ausschnitt, keine automatische Produkterkennung.',faq4:'Was passiert mit meinen Fotos und Raumdaten?',faq4Body:'Diese Demo erstellt oder speichert keine eigenen Fotos, Scans oder Konten. Das eingebettete 3D-Modell wird von Sketchfab geladen. Wer eine Anzeige oder Produktsuche öffnet, wechselt zur jeweiligen Plattform. Ein späterer echter Scanner benötigt ein eigenes Datenschutz- und Speicherkonzept.',faq5:'Wie kommt mein zusätzliches Möbelmodell hinein?',faq5Body:'Eine zusätzliche 3D-Datei kann nach Bereitstellung in die separate Platzierungsszene integriert und in Maßstab, Material und Ausrichtung angepasst werden. Für echtes gemeinsames Platzieren im Originalraum werden zusätzlich nutzbare Raumgeometrie und passende Nutzungsrechte benötigt.',honestTitle:'Entdecke, was in deinem Raum steckt.',honestBody:'Der Raum lässt sich vom festen Standpunkt erkunden. Blicktreffer folgen echten Modellteilen; die Kategorien wurden manuell zugeordnet. Scan und KI-Erkennung bleiben simuliert. Preisvergleiche verlinken recherchierte, ähnliche Angebote. Die Möbel-Demo zeigt dieselbe Raumidee von oben und blendet den Flur aus; Käufe finden beim jeweiligen Anbieter statt. Aktuell werden keine Affiliate-Provisionen erfasst.',selfDiscover:'Selbst entdecken ↗',credit:'3D-Modell:',creditBy:'von',creditOn:'auf Sketchfab. Objektkategorien wurden anhand der Modellstruktur zugeordnet.',footerTag:'Mehr sehen. Besser entscheiden.',concept:'Konzeptdemo · 2026',reticleLabel:'360-Grad-Blicksteuerung. Nach oben ziehen blickt nach oben; der Standpunkt bleibt fixiert.'});
