let translating=false;
export function translateDynamicText(root=document){if(translating)return;translating=true;const map=dynamicMaps[current];const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(node.parentElement?.closest('script,style'))continue;let value=node.nodeValue,trim=value.trim();if(!trim)continue;if(trim.startsWith('IM FOKUS / ')){const m=trim.match(/^IM FOKUS \/ (\d+) IM RAUM$/);trim=m?`IN FOCUS / ${m[1]} IN ROOM`:'IN FOCUS / 1 OBJECT';}else if(trim.startsWith('IN FOCUS / ')){const m=trim.match(/^IN FOCUS \/ (\d+) IN ROOM$/);trim=m?`IM FOKUS / ${m[1]} IM RAUM`:'IM FOKUS / 1 OBJEKT';}else if(/^\d+ recherchierte Vergleiche · Ähnlichkeit begrenzt$/.test(trim))trim=trim.replace('recherchierte Vergleiche · Ähnlichkeit begrenzt','researched comparisons · similarity limited');else if(/^\d+ researched comparisons · similarity limited$/.test(trim))trim=trim.replace('researched comparisons · similarity limited','recherchierte Vergleiche · Ähnlichkeit begrenzt');else if(/^\d+ Objektgruppen · \d+ Stück bewertet · Bewertete Teilsumme/.test(trim))trim=trim.replace('Objektgruppen','object groups').replace('Stück bewertet','pieces assessed').replace('Bewertete Teilsumme','Assessed partial value');else if(/^\d+ object groups · \d+ pieces assessed · Assessed partial value/.test(trim))trim=trim.replace('object groups','Objektgruppen').replace('pieces assessed','Stück bewertet').replace('Assessed partial value','Bewertete Teilsumme');else if(/^\d+ Vergleichsangebote & Herleitung ansehen ↗$/.test(trim))trim=trim.replace('Vergleichsangebote & Herleitung ansehen ↗','comparison offers & reasoning ↗');else if(/^\d+ comparison offers & reasoning ↗$/.test(trim))trim=trim.replace('comparison offers & reasoning ↗','Vergleichsangebote & Herleitung ansehen ↗');else if(trim==='2 recherchierte Vergleiche · Ähnlichkeit begrenzt')trim='2 researched comparisons · similarity limited';else if(trim==='2 researched comparisons · similarity limited')trim='2 recherchierte Vergleiche · Ähnlichkeit begrenzt';const mapped=map[trim]??trim;if(mapped!==trim||trim!==value.trim())node.nodeValue=value.replace(value.trim(),mapped);}translating=false;}
export function watchDynamicText(){const observer=new MutationObserver(()=>requestAnimationFrame(()=>translateDynamicText()));observer.observe(document.body,{subtree:true,childList:true,characterData:true});return observer;}
export function initLanguage(){applyStatic();}
export function setLanguage(lang){if(lang!=='en'&&lang!=='de')return;current=lang;if(typeof localStorage!=='undefined')localStorage.setItem('raumio-language',lang);applyStatic();listeners.forEach(fn=>fn(current));}
